SELECT pd.*, u.user_name, u.avatar, u.phone FROM pay_details pd LEFT JOIN tb_user u ON pd.user_id = u.user_id WHERE state = 1 AND business_type = "recharge"
and u.user_name like concat('%', #{param.userName} ,'%')
and pd.platform = #{param.platform}
and pd.trade_type = #{param.tradeType}
and pd.pay_time between #{param.startTime} and #{param.endTime}
ORDER BY pd.create_time DESC

SELECT
pd.*,
u.user_name,
u.avatar,
u.phone
FROM
pay_details pd
LEFT JOIN tb_user u ON pd.user_id = u.user_id
WHERE state = 1 AND business_type = 3

    and pd.state = #{param.state}


    and pd.business_type = #{param.businessType}


    and u.user_name like concat('%', #{param.userName} ,'%')


    and pd.platform = #{param.platform}


    and pd.trade_type = #{param.tradeType}


    and pd.pay_time between #{param.startTime} and #{param.endTime}

ORDER BY pd.create_time DESC
